import Foundation

/// The intended order - what the user arranged.
///
/// The source of truth is on the app side. The table on the device is only
/// a projection of this state and may be regenerated by Music when merging
/// plays; then we apply the intent again. Albums are keyed by name, because
/// that is how the browse table divides them; tracks by persistent identifier, because
/// `uniqueID` gets renumbered.
public struct OrderIntent: Codable, Sendable, Equatable {
    /// Album names in display order.
    public var albums: [String]
    /// Album -> persistent track identifiers in display order.
    public var tracks: [String: [UInt64]]
    public var jumpTable: JumpTablePolicy
    public var capturedAt: Date

    public init(albums: [String], tracks: [String: [UInt64]], jumpTable: JumpTablePolicy = .derived, capturedAt: Date = Date()) {
        self.albums = albums
        self.tracks = tracks
        self.jumpTable = jumpTable
        self.capturedAt = capturedAt
    }
}

/// What applying the intent changed and what could not be reproduced.
public struct OrderIntentReport: Sendable {
    /// Albums from the intent that are no longer in the library - skipped.
    public let missingAlbums: [String]
    /// Albums in the library unknown to the intent - appended at the end.
    public let newAlbums: [String]
    /// Tracks from the intent that are not in the album - skipped.
    public let missingTracks: Int
    /// Tracks in the album unknown to the intent - appended at the end of the block.
    public let newTracks: Int
    /// Whether the table after applying differs from the one before.
    public let changed: Bool
}

extension ITLibrary {

    /// Captures the intent from the current table - after writing the order this is the state
    /// we want to be able to restore.
    public func captureOrderIntent(jumpTable: JumpTablePolicy = .derived) -> OrderIntent {
        let all = tracks
        let blocks = albumOrder()
        var perAlbum: [String: [UInt64]] = [:]
        for block in blocks {
            perAlbum[block.album, default: []] += block.trackIndices.map { all[$0].persistentID }
        }
        // An album in several blocks would appear twice; the intent keeps it once.
        var seen: Set<String> = []
        let albums = blocks.map(\.album).filter { seen.insert($0).inserted }
        return OrderIntent(albums: albums, tracks: perAlbum, jumpTable: jumpTable)
    }

    /// Whether the current table already matches the intent.
    public func matches(_ intent: OrderIntent) -> Bool {
        let current = captureOrderIntent(jumpTable: intent.jumpTable)
        return current.albums == intent.albums && current.tracks == intent.tracks
    }

    /// Applies the intent to the library. Albums and tracks unknown to the intent go to
    /// the end in their existing order; missing ones are skipped.
    public func applyingOrderIntent(_ intent: OrderIntent) throws -> (library: ITLibrary, report: OrderIntentReport) {
        guard let index = browseIndex(.album) else { throw AlbumOrderError.noBrowseIndex }
        let all = tracks
        let blocks = albumOrder()

        // Merge blocks of the same album, so the intent can lay it out as one whole.
        var merged: [String: AlbumBlock] = [:]
        var appearance: [String] = []
        for block in blocks {
            if let existing = merged[block.album] {
                merged[block.album] = AlbumBlock(
                    id: existing.id, album: existing.album, artist: existing.artist,
                    range: existing.range, trackIndices: existing.trackIndices + block.trackIndices)
            } else {
                merged[block.album] = block
                appearance.append(block.album)
            }
        }

        let known = Set(intent.albums)
        let missingAlbums = intent.albums.filter { merged[$0] == nil }
        let newAlbums = appearance.filter { !known.contains($0) }
        let albumOrder = intent.albums.filter { merged[$0] != nil } + newAlbums

        var missingTracks = 0
        var newTracks = 0
        var ordered: [AlbumBlock] = []
        var cursor = 0
        for (position, name) in albumOrder.enumerated() {
            let block = merged[name]!
            let byPersistent = Dictionary(block.trackIndices.map { (all[$0].persistentID, $0) }, uniquingKeysWith: { first, _ in first })
            var indices: [Int] = []
            var used: Set<Int> = []
            for id in intent.tracks[name] ?? [] {
                if let slot = byPersistent[id], !used.contains(slot) {
                    indices.append(slot); used.insert(slot)
                } else {
                    missingTracks += 1
                }
            }
            for slot in block.trackIndices where !used.contains(slot) {
                indices.append(slot); used.insert(slot)
                if intent.tracks[name] != nil { newTracks += 1 }
            }
            // The range must match the block length - `trackCount` comes from it,
            // and the jump bar from that. A zero range gave an empty bar.
            ordered.append(AlbumBlock(id: position, album: name, artist: block.artist,
                                      range: cursor..<(cursor + indices.count), trackIndices: indices))
            cursor += indices.count
        }

        let result = try replacingAlbumOrder(ordered, original: index, jumpTable: intent.jumpTable)
        let changed = result.browseIndex(.album)?.entries != index.entries
            || result.jumpTable(.album)?.mhod().rawBody != jumpTable(.album)?.mhod().rawBody
        return (result, OrderIntentReport(
            missingAlbums: missingAlbums, newAlbums: newAlbums,
            missingTracks: missingTracks, newTracks: newTracks, changed: changed))
    }
}

/// The intent on disk, per device:
/// `~/Library/Application Support/<product>/Devices/<GUID>/order-intent.json`.
public struct OrderIntentStore: Sendable {
    public let root: URL

    public init(root: URL) { self.root = root }

    public static func standard(productName: String = ProductInfo.name) throws -> OrderIntentStore {
        return OrderIntentStore(root: try ProductInfo.supportDirectory(named: productName)
            .appendingPathComponent("Devices", isDirectory: true))
    }

    public func url(forDevice guid: String) -> URL {
        root.appendingPathComponent(guid, isDirectory: true).appendingPathComponent("order-intent.json")
    }

    public func load(deviceGUID guid: String) throws -> OrderIntent? {
        let file = url(forDevice: guid)
        guard FileManager.default.fileExists(atPath: file.path) else { return nil }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try decoder.decode(OrderIntent.self, from: Data(contentsOf: file))
    }

    public func save(_ intent: OrderIntent, deviceGUID guid: String) throws {
        let file = url(forDevice: guid)
        try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        try encoder.encode(intent).write(to: file, options: .atomic)
    }
}
